    .io_full                            (_fetchBuffer_io_full)
  );
  FTQ ftq (
    .clock                   (clock),
    .reset                   (reset),
    .io_alloc_ready          (_ftq_io_alloc_ready),
    .io_alloc_valid          (ftq_io_alloc_valid),
    .io_alloc_bits_basePc    (io_in_bits_next_pc),
    .io_alloc_bits_validMask (bpu_io_spec_advance_mask),
    .io_alloc_bits_ras_0     (_bpu_io_spec_ras_0),
    .io_alloc_bits_ras_1     (_bpu_io_spec_ras_1),
    .io_alloc_bits_ras_2     (_bpu_io_spec_ras_2),
    .io_alloc_bits_ras_3     (_bpu_io_spec_ras_3),
    .io_alloc_bits_ras_4     (_bpu_io_spec_ras_4),
    .io_alloc_bits_ras_5     (_bpu_io_spec_ras_5),
    .io_alloc_bits_ras_6     (_bpu_io_spec_ras_6),
    .io_alloc_bits_ras_7     (_bpu_io_spec_ras_7),
    .io_alloc_bits_ras_8     (_bpu_io_spec_ras_8),
    .io_alloc_bits_ras_9     (_bpu_io_spec_ras_9),
    .io_alloc_bits_ras_10    (_bpu_io_spec_ras_10),
    .io_alloc_bits_ras_11    (_bpu_io_spec_ras_11),
    .io_alloc_bits_ras_12    (_bpu_io_spec_ras_12),
    .io_alloc_bits_ras_13    (_bpu_io_spec_ras_13),
    .io_alloc_bits_ras_14    (_bpu_io_spec_ras_14),
    .io_alloc_bits_ras_15    (_bpu_io_spec_ras_15),
    .io_alloc_bits_rasPtr    (_bpu_io_spec_ras_ptr),
    .io_alloc_bits_rasCount  (_bpu_io_spec_ras_count),
    .io_allocIdx             (_ftq_io_allocIdx),
    .io_allocGeneration      (_ftq_io_allocGeneration),
    .io_commit0Valid         (io_ftq_commit0_valid),
    .io_commit0Idx           (io_ftq_commit0_idx),
    .io_commit0Generation    (io_ftq_commit0_generation),
    .io_commit1Valid         (io_ftq_commit1_valid),
    .io_commit1Idx           (io_ftq_commit1_idx),
    .io_commit1Generation    (io_ftq_commit1_generation),
    .io_recoverIdx           (io_bp_recover_ftq_idx),
    .io_recoverGeneration    (io_bp_recover_ftq_generation),
    .io_recoverValid         (_ftq_io_recoverValid),
    .io_recover_basePc       (_ftq_io_recover_basePc),
    .io_recover_ras_0        (_ftq_io_recover_ras_0),
    .io_recover_ras_1        (_ftq_io_recover_ras_1),
    .io_recover_ras_2        (_ftq_io_recover_ras_2),
    .io_recover_ras_3        (_ftq_io_recover_ras_3),
    .io_recover_ras_4        (_ftq_io_recover_ras_4),
    .io_recover_ras_5        (_ftq_io_recover_ras_5),
    .io_recover_ras_6        (_ftq_io_recover_ras_6),
    .io_recover_ras_7        (_ftq_io_recover_ras_7),
    .io_recover_ras_8        (_ftq_io_recover_ras_8),
    .io_recover_ras_9        (_ftq_io_recover_ras_9),
    .io_recover_ras_10       (_ftq_io_recover_ras_10),
    .io_recover_ras_11       (_ftq_io_recover_ras_11),
    .io_recover_ras_12       (_ftq_io_recover_ras_12),
    .io_recover_ras_13       (_ftq_io_recover_ras_13),
    .io_recover_ras_14       (_ftq_io_recover_ras_14),
    .io_recover_ras_15       (_ftq_io_recover_ras_15),
    .io_recover_rasPtr       (_ftq_io_recover_rasPtr),
    .io_recover_rasCount     (_ftq_io_recover_rasCount),
    .io_recoverFlush         (io_is_flush & io_bp_recover_valid),
    .io_recoverSlot1         (io_bp_recover_pc != _ftq_io_recover_basePc),
    .io_flush                (io_is_flush & ~io_bp_recover_valid),
    .io_count                (_ftq_io_count),
    .io_full                 (_ftq_io_full)
  );
  PerfMonitor pm (
    .clock    (clock),
    .event_id (32'h0),
    .data     (64'h1),
    .enable   (idle)
  );
  PerfMonitor pm_1 (
    .clock    (clock),
    .event_id (32'h1),
    .data     (64'h1),
    .enable   (_io_imem_rready_T_2 & ~io_imem_rvalid)
  );
  PerfMonitor pm_2 (
    .clock    (clock),
    .event_id (32'h2),
    .data     (64'h1),
    .enable   (_io_imem_rready_T_2 & io_imem_rvalid & ~work)
  );
  PerfMonitor pm_3 (
    .clock    (clock),
    .event_id (32'h2F),
    .data     (64'h1),
    .enable   (work)
  );
  PerfMonitor pm_4 (
    .clock    (clock),
    .event_id (32'h30),
    .data     (64'h1),
    .enable   (_GEN_0)
  );
  PerfMonitor pm_5 (
    .clock    (clock),
    .event_id (32'h31),
    .data     (64'h1),
    .enable   (fetchPacket_valid_0 & io_imem_rvalid1 & slot0Taken)
  );
  PerfMonitor pm_6 (
    .clock    (clock),
    .event_id (32'h35),
    .data     (64'h1),
    .enable
      (work
       & (fetchPacket_valid_0 & _bpu_io_bp_tagged_hit | fetchPacket_valid_1
          & _bpu_io_bp1_tagged_hit))
  );
  PerfMonitor pm_7 (
    .clock    (clock),
    .event_id (32'h36),
    .data     (64'h1),
    .enable
      (work
       & (fetchPacket_valid_0 & _bpu_io_bp_indirect_hit | fetchPacket_valid_1
          & _bpu_io_bp1_indirect_hit))
  );
  PerfMonitor pm_8 (
    .clock    (clock),
    .event_id (32'h45),
    .data     (64'h1),
    .enable
      (work
       & (fetchPacket_valid_0 & _bpu_io_bp_tage_use_alt | fetchPacket_valid_1
          & _bpu_io_bp1_tage_use_alt))
  );
  PerfMonitor pm_9 (
    .clock    (clock),
    .event_id (32'h6F),
    .data     (64'h1),
    .enable
      (work
       & (fetchPacket_valid_0 & _bpu_io_bp_bimodal_selected | fetchPacket_valid_1
          & _bpu_io_bp1_bimodal_selected))
  );
  PerfMonitor pm_10 (
    .clock    (clock),
    .event_id (32'h46),
    .data     (64'h1),
    .enable   (_bpu_io_tage_alloc)
  );
  PerfMonitor pm_11 (
    .clock    (clock),
    .event_id (32'h47),
    .data     (64'h1),
    .enable
      (work
       & (fetchPacket_valid_0 & _bpu_io_bp_itage_hit | fetchPacket_valid_1
          & _bpu_io_bp1_itage_hit))
  );
  PerfMonitor pm_12 (
    .clock    (clock),
    .event_id (32'h48),
    .data     (64'h1),
    .enable   (_bpu_io_itage_alloc)
  );
  PerfMonitor pm_13 (
    .clock    (clock),
    .event_id (32'h7E),
    .data     (64'h1),
    .enable
      (work
       & (fetchPacket_valid_0 & _bpu_io_bp_loop_hit | fetchPacket_valid_1
          & _bpu_io_bp1_loop_hit))
  );
  PerfMonitor pm_14 (
    .clock    (clock),
    .event_id (32'h57),
    .data     (64'h1),
    .enable   (work)
  );
  PerfMonitor pm_15 (
    .clock    (clock),
    .event_id (32'h58),
    .data     ({62'h0, {1'h0, fetchPacket_valid_0} + {1'h0, fetchPacket_valid_1}}),
    .enable   (work)
  );
  PerfMonitor pm_16 (
    .clock    (clock),
    .event_id (32'h59),
    .data     (64'h1),
    .enable   (_GEN_0)
  );
  PerfMonitor pm_17 (
    .clock    (clock),
    .event_id (32'h5A),
    .data     (64'h1),
    .enable   (captureCandidate & _fetchBuffer_io_full)
  );
  PerfMonitor pm_18 (
    .clock    (clock),
    .event_id (32'h5B),
    .data     (64'h1),
    .enable   (captureCandidate & _ftq_io_full)
  );
  PerfMonitor pm_19 (
    .clock    (clock),
    .event_id (32'h5C),
    .data     (64'h1),
    .enable   (work & ~io_imem_rvalid1 & ~slot0Taken & ~(|io_imem_rresp))
  );
  PerfMonitor pm_20 (
    .clock    (clock),
    .event_id (32'h5D),
    .data     (64'h1),
    .enable   (bpu_io_recover_valid)
  );
  PerfMonitor pm_21 (
    .clock    (clock),
    .event_id (32'h5E),
    .data     (64'h1),
    .enable   (bpu_io_recover_valid & (io_bp_recover_is_call | io_bp_recover_is_ret))
  );
  PerfMonitor pm_22 (
    .clock    (clock),
    .event_id (32'h5F),
    .data     ({59'h0, _ftq_io_count - ftqHighWater}),
    .enable   (_GEN)
  );
  PerfMonitor pm_23 (
    .clock    (clock),
    .event_id (32'h60),
    .data     (64'h1),
    .enable   (io_bp_recover_valid & ~_ftq_io_recoverValid)
  );
  PerfMonitor pm_24 (
    .clock    (clock),
    .event_id (32'h78),
    .data     (64'h1),
    .enable   (_io_imem_arvalid_T & io_in_valid & ~io_is_flush & ~fetchResourcesReady)
  );
  PerfMonitor pm_25 (
    .clock    (clock),
    .event_id (32'h79),
    .data     (64'h1),
    .enable   (_io_imem_arvalid_T & ~io_in_valid & ~io_is_flush)
  );
  PerfMonitor pm_26 (
    .clock    (clock),
    .event_id (32'h7A),
    .data     (64'h1),
    .enable   (work & slot1RawUse & ~io_slot1_enable)
  );
  PerfMonitor pm_27 (
    .clock    (clock),
    .event_id (32'h34),
    .data     (64'h1),
    .enable   (redirectBubble_REG & ~(_fetchBuffer_io_out_valid & io_out_ready))
  );
  assign io_in_ready = ~io_in_valid | work | io_is_flush;
  assign io_out_valid = _fetchBuffer_io_out_valid;
  assign io_pc_valid = ~reset & io_pc_ready;
  assign io_pc_bits_next_pc =
    io_is_flush
      ? io_correct_pc
      : slot0Taken
          ? _bpu_io_bp_target
          : slot1CanUse & _bpu_io_bp1_valid & _bpu_io_bp1_taken
              ? _bpu_io_bp1_target
              : slot1CanUse ? io_in_bits_next_pc + 32'h8 : bpu_io_predict_pc1;
  assign io_imem_araddr = io_in_bits_next_pc;
  assign io_imem_arvalid = io_imem_arvalid_0;
  assign io_imem_rready = work | _io_imem_rready_T | _io_imem_rready_T_2 & io_is_flush;
endmodule

